def do_algebra(operator, operand):
    import operator as op

    # Ensure the lengths of the operator and operand lists are valid
    if len(operator) != len(operand) - 1:
        raise ValueError("The length of the operator list must be one less than the operand list.")

    # Initialize the result with the first operand
    result = operand[0]

    # Iterate over the operator and operand lists, applying the operations
    for op_func, num in zip(operator, operand[1:]):
        if op_func == '+':
            result = result + num
        elif op_func == '-':
            result = result - num
        elif op_func == '*':
            result = result * num
        elif op_func == '//':
            result = result // num
        elif op_func == '**':
            result = result ** num
        else:
            raise ValueError(f"Unsupported operator: {op_func}")

    return result
```

